import React, { useState } from "react";
import "./App.css";

function App() {
  const [disease, setDisease] = useState("");
  const [intent, setIntent] = useState("");
  const [location, setLocation] = useState("");

  const [summary, setSummary] = useState("");
  const [publications, setPublications] = useState([]);
  const [trials, setTrials] = useState([]);
  const [chatHistory, setChatHistory] = useState([]);
  const [loading, setLoading] = useState(false);

  const handleSearch = async () => {
    if (!intent) return alert("Ask a question");

    setLoading(true);

    const userMessage = {
      type: "user",
      text: intent,
    };

    try {
      const res = await fetch("http://localhost:8000/analyze", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          disease,
          intent,
          location,
        }),
      });

      const data = await res.json();

      const botMessage = {
        type: "bot",
        summary: data.summary,
      };

      setChatHistory((prev) => [...prev, userMessage, botMessage]);
      setSummary(data.summary || "");
      setPublications(data.publications || []);
      setTrials(data.clinical_trials || []);
    } catch (err) {
      console.error(err);
      alert("Backend error");
    }

    setLoading(false);
  };

  return (
    <div className="app">

      {/* SIDEBAR */}
      <div className="sidebar">
        <h2>AI Medical Copilot</h2>

        <button className="new-btn">+ New Investigation</button>

        <div className="filters">
          <p>Insight Filters</p>
          <label><input type="checkbox" defaultChecked /> Publications</label>
          <label><input type="checkbox" defaultChecked /> Clinical trials</label>
          <label><input type="checkbox" defaultChecked /> Risk analysis</label>
        </div>

        <div className="history">
          <p>Chat History</p>
          {chatHistory
            .filter((msg) => msg.type === "user")
            .map((msg, i) => (
              <div key={i} className="history-item">
                {msg.text}
              </div>
            ))}
        </div>
      </div>

      {/* MAIN */}
      <div className="main">

        {/* TOP STATS */}
        <div className="top-stats">
          <div>Publications <span>{publications.length}</span></div>
          <div>Clinical Trials <span>{trials.length}</span></div>
          <div>Risk Confidence <span>0%</span></div>
          <div>Pipeline Time <span>~250ms</span></div>
        </div>

        <h1>Turn complex medical questions into ranked evidence</h1>

        {/* CHAT */}
        <div className="chat-box">
          {chatHistory.map((msg, i) => (
            <div key={i} className={msg.type === "user" ? "user-msg" : "bot-msg"}>
              {msg.type === "user" ? (
                msg.text
              ) : (
                <p>{msg.summary}</p>
              )}
            </div>
          ))}
        </div>

        {/* INPUT */}
        <textarea
          placeholder="Ask your medical research question..."
          value={intent}
          onChange={(e) => setIntent(e.target.value)}
        />

        <button onClick={handleSearch}>
          {loading ? "Analyzing..." : "Run reasoning copilot"}
        </button>

        {/* STRUCTURED INPUT */}
        <div className="structured">
          <input
            placeholder="Disease"
            value={disease}
            onChange={(e) => setDisease(e.target.value)}
          />
          <input
            placeholder="Location"
            value={location}
            onChange={(e) => setLocation(e.target.value)}
          />
        </div>
      </div>

      {/* RIGHT PANEL */}
      <div className="right">

        <div className="card">
          <h3>Research papers</h3>
          {publications.length === 0 ? (
            <p>No data yet</p>
          ) : (
            publications.map((p, i) => (
              <div key={i} className="item">
                {p.title}
              </div>
            ))
          )}
        </div>

        <div className="card">
          <h3>Clinical trials</h3>
          {trials.length === 0 ? (
            <p>No trials found</p>
          ) : (
            trials.map((t, i) => (
              <div key={i} className="item">
                {t.title}
              </div>
            ))
          )}
        </div>

        <div className="card">
          <h3>Risk analysis</h3>
          <p>Coming soon...</p>
        </div>
      </div>
    </div>
  );
}

export default App;
